import { describe, expect, it } from 'vitest';
import type { TaskEntry } from './contract';
import golden from './fixtures/sheet-block.golden.md?raw';
import sums from './fixtures/sheet-block.SHA256?raw';
import {
  abnahmeOf,
  allTicked,
  groupOf,
  parseAcceptance,
  parseSheets,
  progress,
  rowsOf,
  tickedOf,
  tickItem,
  troubleOf,
  waiting,
} from './abnahme';

const BLOCK = [
  '<!-- testing:sheets:begin -->',
  '## Test sheets',
  '',
  '_Generated by `testing sheets report --tasks`; edit the sheet, not this block (ticked boxes are kept)._',
  '',
  '- **:UI option float** (`ui.option-float`, `ui.nvim/TESTS/sheets/ui-option-float.sheet.lua`): automated part green, waiting for your judgement',
  '  - Judge:',
  '    - [ ] The rows and texts of the float read well',
  '    - [x] The border is visible',
  '  - By hand:',
  '    - [ ] In the real config the cheatsheet key <M-h> opens the same float',
  '  - Look at: `ui.nvim/TESTS/__snapshots__/sheets/ui-option-float.sheet/float.80x24.snap`, `ui.nvim/TESTS/__snapshots__/sheets/ui-option-float.sheet/b.80x24.snap`',
  '- **Done sheet** (`ui.done`, `ui.nvim/TESTS/sheets/done.sheet.lua`): green',
  '  - Judge:',
  '    - [ ] Not waiting, the sheet is green',
  '<!-- testing:sheets:states ui.option-float=inbox ui.done=green -->',
  '<!-- testing:sheets:end -->',
].join('\n');

const body = (block: string) => `## Kontext\n\ntext\n\n${block}\n\n## Notizen\n`;

describe('the sheet block', () => {
  it('is read as sheets with their criteria, snapshots and the state of the states line', () => {
    const sheets = parseSheets(body(BLOCK));
    expect(sheets.map((s) => [s.id, s.state, s.title])).toEqual([
      ['ui.option-float', 'inbox', ':UI option float'],
      ['ui.done', 'green', 'Done sheet'],
    ]);
    const float = sheets[0]!;
    expect(float.items.map((i) => [i.kind, i.text, i.checked])).toEqual([
      ['judge', 'The rows and texts of the float read well', false],
      ['judge', 'The border is visible', true],
      ['manual', 'In the real config the cheatsheet key <M-h> opens the same float', false],
    ]);
    expect(float.snapshots).toEqual([
      'ui.nvim/TESTS/__snapshots__/sheets/ui-option-float.sheet/float.80x24.snap',
      'ui.nvim/TESTS/__snapshots__/sheets/ui-option-float.sheet/b.80x24.snap',
    ]);
  });

  it('is not read when it is broken or missing', () => {
    expect(parseSheets('## Kontext\n- [ ] not a block\n')).toEqual([]);
    expect(parseSheets(body(BLOCK.replace('<!-- testing:sheets:end -->', '')))).toEqual([]);
    expect(parseSheets(body(`${BLOCK}\n${BLOCK}`))).toEqual([]);
  });

  it('waits for a person only in the sheets that are inbox or manual and have criteria', () => {
    const sheets = parseSheets(body(BLOCK));
    expect(waiting(sheets).map((s) => s.id)).toEqual(['ui.option-float']);
    expect(progress(sheets)).toEqual({ ticked: 1, total: 3 });
    expect(allTicked(sheets)).toBe(false);
  });

  it('offers done when every criterion of the waiting sheets is ticked, and not for a sheet without any', () => {
    const ticked = BLOCK.replaceAll('- [ ] The rows', '- [x] The rows').replace('- [ ] In the real', '- [x] In the real');
    expect(allTicked(parseSheets(body(ticked)))).toBe(true);
    const none = BLOCK.replace('ui.option-float=inbox', 'ui.option-float=green');
    expect(allTicked(parseSheets(body(none)))).toBe(false);
  });

  it('keeps the states of a sheet that does not load apart (it has no id)', () => {
    const broken = [
      '<!-- testing:sheets:begin -->',
      '- **ui.nvim/TESTS/sheets/x.sheet.lua** (`ui.nvim/TESTS/sheets/x.sheet.lua`): does not load',
      '<!-- testing:sheets:states x.sheet.lua=red -->',
      '<!-- testing:sheets:end -->',
    ].join('\n');
    const [sheet] = parseSheets(broken);
    expect(sheet?.id).toBeUndefined();
    expect(sheet?.state).toBeUndefined();
  });
});

describe('a tick', () => {
  it('changes the one line of the box and nothing else', () => {
    const text = body(BLOCK);
    const item = parseSheets(text)[0]!.items[0]!;
    const next = tickItem(text, item, true)!;
    expect(next.split('\n').filter((l, i) => l !== text.split('\n')[i])).toEqual([
      '    - [x] The rows and texts of the float read well',
    ]);
    expect(tickItem(next, { ...item }, false)).toBe(text);
  });

  it('is refused when the line is no longer that box (the body changed since it was read)', () => {
    const text = body(BLOCK);
    const item = parseSheets(text)[0]!.items[0]!;
    expect(tickItem(text, { line: item.line, text: 'another criterion' }, true)).toBeNull();
    expect(tickItem(text, { line: 0, text: item.text }, true)).toBeNull();
    expect(tickItem(text, { line: 9999, text: item.text }, true)).toBeNull();
  });

  it('keeps a carriage return of the line', () => {
    const text = body(BLOCK).replaceAll('\n', '\r\n');
    const sheets = parseSheets(text);
    const item = sheets[0]!.items[0]!;
    expect(item.text).toBe('The rows and texts of the float read well');
    expect(tickItem(text, item, true)).toContain('    - [x] The rows and texts of the float read well\r\n');
  });
});

// The block is a contract with testing.nvim (docs/SHEETS.md there): this app reads its text and ticks boxes back. The
// golden block is a copy of testing.nvim's TESTS/golden/sheet-block/sheet-block.golden.md; its checksum file is a copy of
// the one next to it. A copy that was edited by hand fails the first test; a new golden block from testing.nvim is taken
// over by copying both files (and the expectations below, when the format was extended on purpose).
describe('the golden block of testing.nvim', () => {
  it('is the copy its checksum names (an edited copy is reported here)', async () => {
    const bytes = new TextEncoder().encode(golden);
    const sha = [...new Uint8Array(await crypto.subtle.digest('SHA-256', bytes))].map((b) => b.toString(16).padStart(2, '0')).join('');
    expect(`${sha}  sheet-block.golden.md
`).toBe(sums);
  });

  it('is read as the sheets, criteria, ticks and snapshots testing.nvim wrote', () => {
    const sheets = parseSheets(body(golden.trimEnd()));
    // the third sheet does not load: no id, but its state comes from its file name in the states line
    expect(sheets.map((s) => [s.id, s.state, s.title])).toEqual([
      ['picker', 'inbox', 'The picker opens and closes'],
      ['menu', 'manual', 'The menu'],
      [undefined, 'red', 'ui.nvim/TESTS/sheets/broken.sheet.lua'],
    ]);
    expect(sheets).toHaveLength(3);
    const picker = sheets[0]!;
    expect(picker.items.map((i) => [i.kind, i.text, i.checked])).toEqual([
      ['judge', 'the border is visible', true],
      ['judge', 'the title is centred', false],
      ['manual', 'open it with the real mouse', false],
    ]);
    expect(picker.snapshots).toEqual([
      'ui.nvim/TESTS/__snapshots__/sheets/picker.sheet/open.80x24.snap',
      'ui.nvim/TESTS/__snapshots__/sheets/picker.sheet/closed.80x24.snap',
    ]);
    expect(sheets[1]!.items.map((i) => [i.kind, i.text])).toEqual([
      ['manual', 'right-click a file'],
      ['manual', 'choose Rename'],
    ]);
  });
});

describe('the tasks of the view', () => {
  type Counts = Partial<Record<'red' | 'stale' | 'never' | 'inbox' | 'manual' | 'green', number>>;
  const ZERO = { red: 0, stale: 0, never: 0, inbox: 0, manual: 0, green: 0 };
  /** A task with a block whose sheets are `counts` (the worst one is the state, as the engine reads it). */
  const sheet = (id: string, counts: Counts, status = 'open') => {
    const all = { ...ZERO, ...counts };
    const state = (['red', 'stale', 'never', 'inbox', 'manual', 'green'] as const).find((s) => all[s] > 0) ?? 'unknown';
    const total = Object.values(all).reduce((a, b) => a + b, 0);
    return { id, status, tags: [], sheets: { state, total, counts: all } } as unknown as TaskEntry;
  };
  /** A task without a block. */
  const plain = (id: string, tags: string[], status = 'open', actor?: string) =>
    ({ id, status, tags, ...(actor ? { actor } : {}) }) as unknown as TaskEntry;
  const ids = (tasks: readonly TaskEntry[]) => tasks.map((x) => x.id);

  it('with a sheet only: a waiting sheet makes the group (inbox before manual), red, green or none of them waits for nothing', () => {
    const got = abnahmeOf([
      sheet('a', { inbox: 1 }),
      sheet('b', { red: 1 }),
      sheet('d', { manual: 2 }),
      sheet('e', { green: 3 }),
      sheet('f', { inbox: 1, manual: 1 }),
      sheet('g', {}),
    ]);
    expect([ids(got.inbox), ids(got.manual), ids(got.hand)]).toEqual([['a', 'f'], ['d'], []]);
  });

  it('by hand only: a live check without a block (needs-live-test), open, doing or a decision', () => {
    const got = abnahmeOf([
      plain('h1', ['needs-live-test']),
      plain('h2', ['needs-live-test', 'other'], 'doing'),
      plain('h3', ['needs-live-test'], 'decision'),
      plain('x', ['other']),
    ]);
    expect([ids(got.inbox), ids(got.manual), ids(got.hand)]).toEqual([[], [], ['h1', 'h2', 'h3']]);
    expect(groupOf(plain('h1', ['needs-live-test']))).toBe('hand');
  });

  it('mixed red and waiting: shown with its waiting sheet, and the red one is named', () => {
    const mixed = sheet('m', { red: 1, inbox: 1 });
    expect(mixed.sheets?.state).toBe('red');
    expect(ids(abnahmeOf([mixed]).inbox)).toEqual(['m']);
    expect(troubleOf(mixed)).toEqual({ red: 1, stale: 0, never: 0 });
    expect(troubleOf(sheet('s', { stale: 1, manual: 1 }))).toEqual({ red: 0, stale: 1, never: 0 });
    expect(troubleOf(sheet('a', { inbox: 1, green: 2 }))).toBeNull();
    expect(troubleOf(plain('h', ['needs-live-test']))).toBeNull();
  });

  it('parked, blocked or done: waits for nothing, by hand or with a sheet waiting by hand', () => {
    const got = abnahmeOf([
      plain('p', ['needs-live-test'], 'parked'),
      plain('b', ['needs-live-test'], 'blocked'),
      plain('d', ['needs-live-test'], 'done'),
    ]);
    expect([ids(got.inbox), ids(got.manual), ids(got.hand)]).toEqual([[], [], []]);
  });

  it('actor me without the tag is not a live check, with or without boxes; with a block it is a sheet task', () => {
    const got = abnahmeOf([plain('me1', [], 'open', 'me'), plain('me2', ['needs-user'], 'open', 'me')]);
    expect([ids(got.inbox), ids(got.manual), ids(got.hand)]).toEqual([[], [], []]);
    expect(groupOf(sheet('me3', { manual: 1 }))).toBe('manual');
    // a live check that has a block is a sheet task, not one by hand
    expect(groupOf({ ...sheet('t', { green: 1 }), tags: ['needs-live-test'] } as TaskEntry)).toBeNull();
  });

  it('the boxes of the acceptance section are the points of a task by hand', () => {
    const text = [
      '## Kontext',
      '',
      '- [ ] not acceptance',
      '',
      '## Akzeptanz',
      '',
      '- [ ] On a real account',
      '- [x] On the Mac',
      '  - [ ] nested, still a point',
      '',
      '```',
      '- [ ] in a code block',
      '```',
      '### A sub heading stays inside',
      '- [ ] after it\r',
      '',
      '## Notizen',
      '',
      '- [ ] not acceptance either',
    ].join('\n');
    const items = parseAcceptance(text);
    expect(items.map((i) => [i.kind, i.text, i.checked, i.line])).toEqual([
      ['acceptance', 'On a real account', false, 6],
      ['acceptance', 'On the Mac', true, 7],
      ['acceptance', 'nested, still a point', false, 8],
      ['acceptance', 'after it', false, 14],
    ]);
    expect(tickedOf(items)).toEqual({ ticked: 1, total: 4 });
    // a tick rewrites the one line, the CR it had kept
    const ticked = tickItem(text, items[3]!, true)!;
    expect(ticked.split('\n')[14]).toBe('- [x] after it\r');
    expect(parseAcceptance('## Acceptance\n- [ ] english\n')).toHaveLength(1);
    expect(parseAcceptance('No section\n- [ ] box\n')).toEqual([]);
  });

  it('show a snapshot as rows without the empty row after the last newline', () => {
    expect(rowsOf('one\r\ntwo\n')).toEqual(['one', 'two']);
    expect(rowsOf('')).toEqual(['']);
  });
});
